  try {
    return admitEntries(centralEntries(archive, view), limits).map((entry) => ({
      path: entry.path,
      read: () => memberBytes(archive, view, entry),
    }));
  } catch (error) {
    if (error instanceof RangeError) {
      throw new ArchiveRefused('unreadable archive');
    }
    throw error;
  }
