function hex(digest: ArrayBuffer): string {
  return Array.from(new Uint8Array(digest), (byte) => byte.toString(16).padStart(2, '0')).join('');
}

@Injectable({ providedIn: 'root' })
export class FilesService {
  private readonly browser = inject(BrowserPlatform);
  private readonly store = inject(StoreService);
  private readonly config = inject(RUNTIME_CONFIG);
  private readonly limits = inject(PACKAGE_LIMITS);

  /** Fetches *url* and keeps its bytes under *key*, answering whether it was kept. */
  async download(url: string, key: string): Promise<boolean> {
    const origin = this.config.offline?.packages;
    if (origin === undefined || !linkAdmitted(url, origin)) {
      return false;
    }
    const bytes = await this.browser.fetchBytes(url);
    if (bytes === null) {
      return false;
    }
    try {
      await this.store.put(key, base64OfBytes(bytes));
      return true;
    } catch {
      return false;
    }
  }

  /**
   * Unpacks the archive kept under *key* into entries `<key>/<path>`, answering the member paths,
   * sorted, or `null` when the archive is refused -- and then nothing under `<key>/` remains.
   */
  async unzip(key: string): Promise<string[] | null> {
    try {
      const kept = await this.store.get(key);
      if (kept === null) {
        return null;
      }
      await this.deleteUnder(key);
      const paths: string[] = [];
      try {
        for (const member of admittedMembers(bytesOfBase64(kept), this.limits)) {
          await this.store.put(`${key}${SEPARATOR}${member.path}`, base64OfBytes(member.read()));
          paths.push(member.path);
        }
      } catch (error) {
        await this.deleteUnder(key);
        if (error instanceof ArchiveRefused || error instanceof RangeError) {
          return null;
        }
        throw error;
      }
      return paths.sort();
    } catch {
      return null;
    }
  }

  /** The SHA-256 of the bytes kept under *key*, as 64 lowercase hex digits, or `null`. */
  async sha256(key: string): Promise<string | null> {
    const subtle = this.browser.subtleCrypto();
    if (subtle === null) {
      return null;
    }
    try {
      const kept = await this.store.get(key);
      return kept === null ? null : hex(await subtle.digest('SHA-256', bytesOfBase64(kept)));
    } catch {
      return null;
    }
  }

  /**
   * Moves every file under `<source>/` to the same path under `<target>/`, answering whether all
   * moved; what `<target>/` held before is removed first.
   */
  async move(source: string, target: string): Promise<boolean> {
    try {
      await this.deleteUnder(target);
      const prefix = `${source}${SEPARATOR}`;
      for (const key of await this.store.keys()) {
        if (!key.startsWith(prefix)) {
          continue;
        }
        const kept = await this.store.get(key);
        if (kept !== null) {
          await this.store.put(`${target}${SEPARATOR}${key.slice(prefix.length)}`, kept);
        }
        await this.store.remove(key);
      }
      return true;
    } catch {
      return false;
    }
  }

  /** Removes the entry *prefix* and every file under `<prefix>/`, answering whether all were removed. */
  async delete(prefix: string): Promise<boolean> {
    try {
      await this.store.remove(prefix);
      await this.deleteUnder(prefix);
      return true;
    } catch {
      return false;
    }
  }

  private async deleteUnder(prefix: string): Promise<void> {
    const under = `${prefix}${SEPARATOR}`;
    for (const key of await this.store.keys()) {
      if (key.startsWith(under)) {
        await this.store.remove(key);
      }
    }
  }
}
